package com.crms.entity;import jakarta.persistence.*;import java.time.Instant;@Entity public class Notification{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private User user;private String title;@Column(length=2000)private String message;private boolean readFlag=false;private Instant createdAt=Instant.now();public Long getId(){return id;}public User getUser(){return user;}public void setUser(User v){user=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getMessage(){return message;}public void setMessage(String v){message=v;}public boolean isReadFlag(){return readFlag;}public void setReadFlag(boolean v){readFlag=v;}public Instant getCreatedAt(){return createdAt;}}
